import{_ as t,o as a,c as n,aw as s}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Объект события (Event)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/dom-events/params-event.md","filePath":"wiki/dev-commit/js/js-web-api/dom-events/params-event.md"}'),l={name:"wiki/dev-commit/js/js-web-api/dom-events/params-event.md"};function o(i,e,r,p,c,v){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="объект-события-event" tabindex="-1">Объект события (Event) <a class="header-anchor" href="#объект-события-event" aria-label="Permalink to &quot;Объект события (Event)&quot;">​</a></h1><ul><li><strong>Event</strong> - объект созданный перед запуском события</li><li>Когда происходит событие, браузер создаёт объект события, записывает в него детали и передаёт его в качестве аргумента функции-обработчику</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> btn</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">getElementById</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;btn&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">btn.</span><span style="color:#4078F2;">addEventListener</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;click&#39;</span><span style="color:#383A42;">, (event) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(event));</span></span></code></pre></div><h2 id="объект-события-event-1" tabindex="-1">Объект события (Event) <a class="header-anchor" href="#объект-события-event-1" aria-label="Permalink to &quot;Объект события (Event)&quot;">​</a></h2><h4 id="возвращает-объект-данные" tabindex="-1">Возвращает объект/данные <a class="header-anchor" href="#возвращает-объект-данные" aria-label="Permalink to &quot;Возвращает объект/данные&quot;">​</a></h4><ul><li>event.type - название события (н-р click)</li><li>event.target - инициатор события</li><li>event.currentTarget - элемент на котором сработал обработчик. Значение – обычно такое же, как и у this, но если обработчик является функцией-стрелкой или при помощи bind привязан другой объект в качестве this, то мы можем получить элемент из event.currentTarget</li><li>event.eventPhase - номер фазы, на которой событие было поймано (Event.CAPTURING_PHASE=1, Event.AT_TARGET=2, Event.BUBBLING_PAGE=3)</li><li>event.timeStamp - объект Date, указывающий, когда произошло событие</li><li>event.bubbles - true если событие может всплывать по дереву элементов. события blur, focus, load, unload не всплывают</li><li>event.cancelable - true если с этим событием связано действие по умолчанию и его можно отменить preventDefault</li><li>event.clientX - координата X курсора в момент клика относительно окна, для событий мыши</li><li>event.clientY - координата Y курсора в момент клика относительно окна, для событий мыши</li></ul><h4 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h4><ul><li>event.preventDefault() - отключение действия события по умолчанию</li><li>event.stopPropagation() - прекращение всплытия</li><li>event.stopImmediatePropagation() - прекращение всплытия и остановка обработки событий на текущем элементе</li></ul>`,8)])])}const m=t(l,[["render",o]]);export{u as __pageData,m as default};
